/// Equivalent to `WikipediaTokenizerImpl.zzUnpackTrans(String, int, int[])`.
fn zz_unpack_trans_packed(packed: &[u16], offset: usize, result: &mut [i32]) -> usize {
    let mut i = 0; /* index in packed string  */
    let mut j = offset; /* index in unpacked array */
    let l = packed.len();
    while i < l {
        let mut count = i32::from(packed[i]);
        i += 1;
        let mut value = i32::from(packed[i]);
        i += 1;
        value -= 1;
        loop {
            result[j] = value;
            j += 1;
            count -= 1;
            if count <= 0 {
                break;
            }
        }
    }
    j
}

